using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using HarborValeGreybox.Launch;
using HarborValeGreybox.Driving;
using HarborValeGreybox.Workshop;
namespace HarborValeGreybox.Racing {
public sealed class ComponentsPlayerProbe:MonoBehaviour {
 static string folder;readonly List<string> checks=new List<string>();bool failed;double deadline;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"--components-check-dir");folder=Debug.isDebugBuild&&i>=0&&i+1<a.Length?Path.GetFullPath(a[i+1]):null;if(folder!=null){Directory.CreateDirectory(folder);DocksideTrialDirector.SavePathOverrideForTests=folder+"/isolated-v10.json";}}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Hook(){if(folder!=null){var go=new GameObject("Paid components and circuit native verification");DontDestroyOnLoad(go);go.AddComponent<ComponentsPlayerProbe>();}}
 void Check(bool ok,string text){checks.Add((ok?"PASS ":"FAIL ")+text);File.WriteAllLines(folder+"/results.txt",checks);if(!ok){failed=true;Application.Quit(1);throw new Exception(text);}}
 void OnEnable(){Application.logMessageReceived+=Log;}void OnDisable(){Application.logMessageReceived-=Log;}void Log(string t,string trace,LogType type){if(!failed&&(type==LogType.Error||type==LogType.Exception))Check(false,"Runtime error: "+t);}void Update(){if(deadline>0&&!failed&&Time.realtimeSinceStartupAsDouble>deadline)Check(false,"Components native timeout");}
 IEnumerator Wait(Func<bool> condition){while(!condition())yield return null;yield return new WaitForSecondsRealtime(.25f);}IEnumerator Capture(string name){yield return new WaitForSecondsRealtime(.4f);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(folder+"/"+name+".png");yield return new WaitForSecondsRealtime(.5f);Check(new FileInfo(folder+"/"+name+".png").Length>50000,"Nonblank native render: "+name);}
 static TrialSession Finish(TrialDefinition d){var s=new TrialSession(d);s.Tick(4,Vector3.zero,Vector3.zero);s.Tick(90,Vector3.zero,Vector3.zero);foreach(var g in d.checkpoints)s.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward);return s;}
 IEnumerator Start(){Application.runInBackground=true;deadline=Time.realtimeSinceStartupAsDouble+600;yield return Wait(()=>HarborValeLaunch.Instance!=null);HarborValeLaunch.Instance.Open(HarborValeLaunch.CityScene);yield return Wait(()=>CircuitRaceDirector.Instance?.Ready==true&&FindAnyObjectByType<ExpandedWorkshop>()?.Ready==true);var circuit=CircuitRaceDirector.Instance;var duel=RivalRaceDirector.Instance;var trial=duel.Trial;var store=trial.Store;var car=trial.vehicle;car.externalInput=true;car.commandedHandbrake=false;car.commandedServiceBrake=1;car.ResetAt(PhysicalGarage.Instance.Building.TransformPoint(new Vector3(0,.35f,-1)),PhysicalGarage.Instance.Building.rotation);for(int i=0;i<100;i++)store.Settle(Finish(trial.Definition),out _);yield return new WaitForSecondsRealtime(.8f);var shop=FindAnyObjectByType<ExpandedWorkshop>();Check(shop.Open(),"Real G garage opens at stopped physical building");shop.OpenUpgradeMode();foreach(var part in shop.Catalog.MissingPath(shop.Build,shop.Catalog.Find("induction_small_2")))Check(shop.Install(part.id),"Actual sequential paid hardware: "+part.id);shop.OpenInventoryMode();shop.OpenComponentsMode();Screen.SetResolution(1400,800,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.4f);Screen.SetResolution(1280,720,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.6f);var ui=shop.ComponentView;int cash=store.Profile.availableCredits;string carId=store.Profile.fleet.selectedId;yield return Capture("Parts_Labor_Bench");bool interactive=Environment.GetCommandLineArgs().Contains("--components-interactive");if(interactive){File.WriteAllText(folder+"/ready-for-removal.txt",carId);yield return Wait(()=>store.Profile.fleet.parts.Any(p=>p.status=="stored"));Check(true,"Physical mouse removal drag and paid confirmation commit real turbo kit");}else{Check(ui.BeginRemove(carId,"induction")&&ui.Confirm(),"GUI removal quote and paid confirmation commit real turbo kit");}Check(store.Profile.availableCredits==cash-250&&!car.Engine.definition.IsTurbo&&shop.Build.induction=="none","Removal charges250once and updates actual boost/powertrain");string kit=store.Profile.fleet.parts.Single().id;yield return Capture("Stored_Turbo_Kit");if(interactive){File.WriteAllText(folder+"/ready-for-refit.txt",kit);yield return Wait(()=>store.Profile.fleet.parts.Single().status=="installed");Check(true,"Physical stored-kit drag into induction slot and confirmation refit correctly");}else Check(ui.BeginFit(kit,carId)&&ui.Confirm(),"GUI refits owned kit for labor");Check(store.Profile.availableCredits==cash-500&&shop.Build.inductionStage==2&&car.Engine.definition.IsTurbo&&store.Profile.fleet.parts.Count==1,"Refit restores Stage2 torque/boost and unique identity without repurchasing kit");yield return Capture("Turbo_Refitted");shop.Close();yield return new WaitForSecondsRealtime(.5f);Check(circuit.Open(),"Paid circuit opens while stopped");Check(!circuit.Enter()&&!store.Profile.fleet.HasPending,"Unconfirmed entry cannot debit credits");yield return Capture("Eight_Car_Entry_Menu");int entryCash=store.Profile.availableCredits;circuit.EntryConfirmed=true;Check(circuit.Enter()&&store.Profile.availableCredits==entryCash-3000,"Confirmed eight-car entry charges3000and persists terms");Check(circuit.Opponents.Length==7&&circuit.Opponents.All(p=>p.Car.Wheels.Length==4&&!p.Car.Body.isKinematic),"Seven distinct physical AI rivals spawn with four contacts each");Check(circuit.Opponents.Any(p=>p.Car.Engine.definition.aspiration=="supercharged")&&circuit.Opponents.Any(p=>p.Car.PowertrainCarId=="car_tempest"),"Live field includes supercharged muscle and Tempest exotic");Check(!shop.Open(),"Paid garage is blocked during committed circuit");yield return Capture("Eight_Car_Starting_Grid");var driver=car.gameObject.AddComponent<RoadPilot>();driver.Car=car;driver.Path=trial.Definition.route.Select(p=>p.Position).ToArray();driver.IsRival=driver.ClosedCourse=true;driver.CruiseKph=105;driver.SeedClosedGrid(true);Time.timeScale=3;bool image=false;while(!circuit.Results&&!circuit.SavePending){driver.Held=circuit.Session.Player.State!=TrialState.Running;if(!image&&circuit.Session.Player.NextGate>=6){image=true;yield return Capture("Eight_Car_Live_Circuit");}yield return null;}Time.timeScale=1;Destroy(driver);Check(circuit.Results&&!circuit.SavePending&&circuit.Session.Player.ValidFinish,"Real native eight-car player run completes all37 gates");var session=circuit.Session;int payout=session.Result.beaten*1000;Check(store.Profile.availableCredits==entryCash-3000+payout&&session.Result.beaten>=0&&session.Result.beaten<=7,"Actual native finish pays1000per beaten rival after3000entry");int paid=store.Profile.availableCredits;store.SettleCircuit(session);Check(store.Profile.availableCredits==paid,"Native result retry cannot duplicate prize");yield return Capture("Eight_Car_Cash_Result");Check(new RaceProgressStore(store.PathName,trial.Definition).Profile.availableCredits==paid,"Native components and circuit save reload validates");circuit.ReturnToRoad();car.ResetAt(PhysicalGarage.Instance.Building.TransformPoint(new Vector3(0,.35f,-1)),PhysicalGarage.Instance.Building.rotation);car.externalInput=true;car.commandedPedal=0;car.commandedServiceBrake=1;yield return new WaitForSecondsRealtime(.8f);Check(circuit.Open(),"Can reopen event after valid result");circuit.EntryConfirmed=true;Check(circuit.Enter()&&circuit.BeforeLeave(),"Confirmed subsequent entry can be deliberately forfeited");Check(store.Profile.availableCredits==paid-3000&&FleetLedger.Find(store.Profile.fleet,carId).owner=="player"&&!store.Profile.fleet.HasPending,"Forfeit loses only entry fee and preserves car/kit ownership");circuit.ReturnToRoad();string saved=File.ReadAllText(store.PathName);HarborValeLaunch.Instance.Open(HarborValeLaunch.MenuScene);yield return Wait(()=>!HarborValeLaunch.Instance.Busy);ExpandedWorkshop.RequestedTestModel="car_tempest";HarborValeLaunch.Instance.Open(HarborValeLaunch.SportsScene);yield return Wait(()=>FindAnyObjectByType<ExpandedWorkshop>()?.Ready==true);Check(File.ReadAllText(DocksideTrialDirector.SavePathOverrideForTests)==saved,"Free Tempest remains byte-isolated from v10 paid components/circuit ledger");Check(!failed,"Components/circuit native run has no runtime errors");Application.Quit(0);}
}
}
